# Doctor summary from stream
python3 << 'PY'
import json, pathlib
p = pathlib.Path("$EVID/baseline/04-doctor-all.stream.jsonl".replace("$EVID", "/Users/nckrtl/orbit/.worktrees/codex-live-candidate-ade-removal/.orbit/release-evidence/2026-08-04-live-candidate-ade-removal"))
lines = p.read_text().splitlines()
print("events", len(lines))
# last few events
for line in lines[-5:]:
    try:
        e=json.loads(line)
    except Exception:
        print("RAW", line[:300])
        continue
    print(e.get("event"), json.dumps(e.get("data") if isinstance(e.get("data"), dict) else e)[:500])
# collect final results / failures
final = None
for line in reversed(lines):
    try:
        e=json.loads(line)
    except Exception:
        continue
    if e.get("event") in ("result","final","done","complete") or (isinstance(e.get("data"), dict) and e.get("data",{}).get("status") in ("failed","passed","completed")):
